import itertools, json
jobs='ABCDE'
slot={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
tr=dict(zip(jobs,[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def nominal(r):
    return sum(slot[j][i] for i,j in enumerate(r))+sum(tr[a][jobs.index(b)] for a,b in zip(r,r[1:]))
def incident(r,s):
    p={j:r.index(j)+1 for j in jobs}
    if p['A']>=p['D']: return None
    if s=='rain':
        if p['D']==1 or p['A']==1: return None
        return nominal(r)+6*max(0,p['C']-1)
    if s=='road':
        if p['C']==4 or p['E']==2: return None
        return nominal(r)+6*max(0,p['D']-3)
    if s=='lift':
        if p['A']==1 or p['B']==1: return None
        return nominal(r)+10*max(0,p['E']-2)
def neighbors(r):
    yield r,0
    for i,j in itertools.combinations(range(5),2):
        t=list(r); t[i],t[j]=t[j],t[i]
        yield ''.join(t),1
records=[]
for tup in itertools.permutations(jobs):
    r=''.join(tup)
    if r.index('A')>r.index('D'): continue
    repairs={}; costs={}
    for s in ('rain','road','lift'):
        choices=[(incident(t,s)+fee,t) for t,fee in neighbors(r) if incident(t,s) is not None]
        if not choices: break
        costs[s],repairs[s]=min(choices)
    else: records.append((nominal(r)+max(costs.values()),r,repairs,costs))
records.sort()
best=records[0]
answer={'roster':best[1],'score':best[0],'repairs':best[2],'repair_costs':best[3],'feasible_count':len(records),'next_score':min(t[0] for t in records if t[0]>best[0])}
payload=json.dumps(answer,separators=(',',':'))
# Independent verification: scan all final permutations and allow Hamming distance 0 or 2.
allr=[''.join(t) for t in itertools.permutations(jobs)]
verified=[]
for r in allr:
    if r.index('A')>=r.index('D'): continue
    values=[]
    for s in ('rain','road','lift'):
        candidates=[]
        for t in allr:
            dif=sum(a!=b for a,b in zip(r,t))
            if dif not in (0,2) or t.index('A')>=t.index('D'): continue
            a,b,c,d,e=[t.index(j)+1 for j in jobs]
            if (s=='rain' and (d==1 or a==1)) or (s=='road' and (c==4 or e==2)) or (s=='lift' and (a==1 or b==1)): continue
            base=sum(slot[t[k]][k] for k in range(5))+sum(tr[t[k]][ord(t[k+1])-65] for k in range(4))
            penalty={'rain':6*(c-1),'road':6*max(d-3,0),'lift':10*max(e-2,0)}[s]
            candidates.append((base+penalty+(dif==2),t))
        if not candidates: break
        values.append(min(candidates)[0])
    else: verified.append((nominal(r)+max(values),r))
decoded=json.loads(payload)
assert decoded['score']==min(x[0] for x in verified)
assert decoded['feasible_count']==len(verified)
assert decoded['next_score']==min(x[0] for x in verified if x[0]>decoded['score'])
for s,t in decoded['repairs'].items():
    opts=[(incident(u,s)+f,u) for u,f in neighbors(decoded['roster']) if incident(u,s) is not None]
    assert decoded['repair_costs'][s]==min(opts)[0]
    assert (decoded['repair_costs'][s],t) in opts
assert decoded['score']==nominal(decoded['roster'])+max(decoded['repair_costs'].values())
print(payload)
print('Verified all fields by exhaustive enumeration; publication nominal:',nominal(decoded['roster']))

