import itertools,json
start='AECBD'; jobs='ABCDE'
slots=[[0,1,4,11,3],[2,3,3,2,5],[4,8,2,10,8],[3,2,11,3,4],[10,6,10,10,4]]
trans=[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]
def neighbors(r):
    for i,j in itertools.combinations(range(5),2):
        t=list(r);t[i],t[j]=t[j],t[i]
        yield ''.join(t)
distance={start:0}
for d in range(2):
    for r in [r for r in distance if distance[r]==d]:
        for t in neighbors(r): distance.setdefault(t,d+1)
def legal(r):
    return r.index('A')<r.index('D') and r[0] not in 'AD' and r[3]!='B'
def cost(r,d):
    ix=[jobs.index(j) for j in r]
    return sum(slots[j][i] for i,j in enumerate(ix))+sum(trans[a][b] for a,b in zip(ix,ix[1:]))+6*r.index('C')+d+(4 if d==2 else 0)
classes={str(d):[(cost(r,d),r) for r,k in distance.items() if k==d and legal(r)] for d in range(3)}
best=min(item for group in classes.values() for item in group)
answer={'roster':best[1],'score':best[0],'best_by_swaps':{d:min(x[0] for x in group) if group else None for d,group in classes.items()},'feasible_by_swaps':{d:len(group) for d,group in classes.items()}}
payload=json.dumps(answer,separators=(',',':'))
a=json.loads(payload)
# Independent minimum-distance check via permutation cycles over all 120 rosters.
check={str(d):[] for d in range(3)}
for t in itertools.permutations(jobs):
    r=''.join(t); perm=[start.index(j) for j in r]; seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1; k=i
            while k not in seen: seen.add(k); k=perm[k]
    d=5-cycles
    if d<=2 and legal(r): check[str(d)].append((cost(r,d),r))
assert a['best_by_swaps']=={d:min(x[0] for x in group) if group else None for d,group in check.items()}
assert a['feasible_by_swaps']=={d:len(group) for d,group in check.items()}
assert (a['score'],a['roster'])==min(x for group in check.values() for x in group)
print(payload)
print('Verified BFS exchange distances against cycle distances for exhaustive permutation enumeration.')

